"""配置加载：config.json 缺失或字段不全时用默认值兜底。"""
import copy
import json
import os

DEFAULTS = {
    "pet": {
        "name": "小云宝",
        "wake_word": "小云宝",
        "persona": "你是一朵软绵绵、白白胖胖的小白云，名字叫小云宝，是海云幼儿园的吉祥物和 AI 助教，听众是 3~6 岁的孩子。",
    },
    "deepseek": {
        "api_key": "",
        "base_url": "https://api.deepseek.com",
        "model": "deepseek-chat",
    },
    "xfyun": {
        "app_id": "",
        "api_key": "",
        "api_secret": "",
    },
    "tts": {
        "voice": "zh-CN-XiaoyiNeural",   # 小艺（活泼少女音）；备选 zh-CN-XiaoxiaoNeural（晓晓）
        "rate": "+8%",
        "volume": 0.9,
    },
    "classroom": {
        "big_font": True,      # 气泡/字幕大字体（教室后排可读）
        "mic_button": True,    # 启动时显示麦克风按钮
        "auto_wake": False,    # 启动时自动开启唤醒词监听（上课时手动开更省额度）
        "mic_device": None,    # 指定麦克风（设备名或索引），None=系统默认
    },
}


def _merge(dst, src):
    for k, v in src.items():
        if isinstance(v, dict) and isinstance(dst.get(k), dict):
            _merge(dst[k], v)
        else:
            dst[k] = v


def load_config(path="config.json"):
    cfg = copy.deepcopy(DEFAULTS)
    if os.path.exists(path):
        try:
            with open(path, encoding="utf-8") as f:
                _merge(cfg, json.load(f))
        except (OSError, ValueError):
            pass
    return cfg

