        "voice": "zh-CN-XiaoxiaoNeural",   # 晓晓（温柔成熟女声，专业助教）；备选 zh-CN-XiaoyiNeural（小艺）
        "rate": "+8%",
        "volume": 0.9,
    },
    "classroom": {
        "big_font": True,      # 气泡/字幕大字体（教室后排可读）
        "mic_button": True,    # 启动时显示麦克风按钮
