def encrypt_keys(d: dict) -> str:
    """把 Key 字典（JSON）加密成 keys.dat 的内容"""
    data = json.dumps(d, ensure_ascii=False).encode("utf-8")
    return base64.b64encode(
        bytes(b ^ _KEYS_XOR[i % len(_KEYS_XOR)] for i, b in enumerate(data))
