    cfg = copy.deepcopy(DEFAULTS)
    p = path or _find_config()
    if p:
        try:
            with open(p, encoding="utf-8") as f:
                _merge(cfg, json.load(f))
        except (OSError, ValueError):
            pass
    _overlay_keys(cfg)
    return cfg

